function sourcePlanTools(model){const scope=document.querySelector('#audit-phase')?.value;return `<section class="source-plan-tools"><h3>Plan a course-only subset from these rules</h3><p>Choose admission preparation or a degree-course subset. The next screen lets you confirm classes and published prerequisite paths. Credit totals, GPA, residency, conditional rules and other unsupported clauses remain review items.</p><label>Planning scope<select id="source-plan-scope"><option value="admission" ${scope!=='degree'?'selected':''}>Admission course preparation</option><option value="degree" ${scope==='degree'?'selected':''}>Degree-course subset</option></select></label><div id="source-plan-alternatives"></div><button class="btn primary" id="create-source-plan" type="button">Create reviewable course draft →</button><p id="source-plan-message" role="status"></p></section>`}
function bindSourcePlanTools(target,model){const scope=target.querySelector('#source-plan-scope'),alternatives=target.querySelector('#source-plan-alternatives'),button=target.querySelector('#create-source-plan'),message=target.querySelector('#source-plan-message');if(!scope)return;const options=()=>({phase:scope.value,route:document.querySelector('#audit-applicant-route')?.value||'unknown',completed:state.courses||[]});const draw=()=>{alternatives.innerHTML=SourcePlanBridge.groups(model,options()).map(group=>`<label>Choose one whole alternative sequence<select data-source-plan-group="${esc(group.id)}"><option value="">Choose a source alternative</option>${group.choices.map(r=>`<option value="${esc(r.id)}">${esc(r.type==='choose-courses'?'Choose '+r.count+' from: '+r.codes.join(', '):r.codes.join(' + '))}</option>`).join('')}</select></label>`).join('');button.disabled=!SourcePlanBridge.available(model,options());message.textContent=button.disabled?'No unconditional course clauses are modeled for this scope and applicant route. Read the source conditions below; this tool will not invent course requirements.':'Course selections are not saved until you create the draft. Existing academic records stay unchanged.'};scope.onchange=draw;draw();button.onclick=()=>{try{const choices=Object.fromEntries([...alternatives.querySelectorAll('[data-source-plan-group]')].map(el=>[el.dataset.sourcePlanGroup,el.value])),draft=SourcePlanBridge.build(model,{...options(),alternatives:choices});const prior=state.catalogDraft;if(prior?.rows?.some(r=>r.confirmed)&&!confirm('Replace the current course draft with this reviewed-source subset? Saved degree goals and completed coursework stay unchanged.'))return;draft.goalId=(state.degreeGoals||[]).find(g=>g.programId===model.id)?.id||'';draft.updatedAt=new Date().toISOString();const checked=WorkspaceSchema.validate({...state,catalogDraft:draft});state.catalogDraft=checked.catalogDraft;catalogPrepared=null;save();location.hash='catalog-draft';render()}catch(error){message.textContent=error.message}}}
